(x, y, t) => {
  const sources = [];
  for (let i = 0; i < 6; i++) {
    const ph = i * 1.0472;
    sources.push({
      x: 240 + Math.sin(t * (0.3 + i * 0.08) + ph) * (110 + i * 14),
      y: 120 + Math.cos(t * (0.25 + i * 0.06) + ph * 1.3) * (55 + i * 9),
      freq: 0.055 + i * 0.013,
      speed: 1.8 + i * 0.3
    });
  }
  let activator = 0, inhibitor = 0;
  for (let i = 0; i < 3; i++) {
    const s = sources[i], d = Math.sqrt((x - s.x) ** 2 + (y - s.y) ** 2);
    activator += Math.sin(d * s.freq - t * s.speed) / (1 + d * 0.003);
  }
  activator /= 3;
  for (let i = 3; i < 6; i++) {
    const s = sources[i], d = Math.sqrt((x - s.x) ** 2 + (y - s.y) ** 2);
    inhibitor += Math.sin(d * s.freq - t * s.speed + 1.5) / (1 + d * 0.004);
  }
  inhibitor /= 3;
  const wx = Math.sin(x * 0.018 + t * 0.3) * 16 + Math.cos(y * 0.022 + t * 0.4) * 11;
  const wy = Math.cos(x * 0.022 - t * 0.35) * 16 + Math.sin(y * 0.018 - t * 0.25) * 11;
  const sx = x + wx, sy = y + wy;
  const pw1 = Math.sin(sx * 0.038 + sy * 0.018 + t * 0.7);
  const pw2 = Math.sin(sx * 0.018 - sy * 0.038 + t * 0.9);
  const pw3 = Math.sin((sx + sy) * 0.075 + t * 2.5) * 0.18;
  const reaction1 = Math.tanh((activator - inhibitor * 0.7 + (pw1 + pw2) * 0.4 + pw3) * 2.2);
  const cx = 240, cy = 120;
  const dist = Math.sqrt((sx - cx) ** 2 + (sy - cy) ** 2);
  const ang = Math.atan2(sy - cy, sx - cx);
  const radial = Math.sin(dist * 0.033 - t * 1.2);
  const angular = Math.sin(ang * 8 + t * 0.3) * 0.55 + Math.sin(ang * 13 - t * 0.5) * 0.3;
  const spiral = Math.sin(dist * 0.018 + ang * 3 - t * 0.8);
  const pattern2 = Math.tanh((radial + angular + spiral * 0.4) * 1.8);
  const fine = Math.sin(x * 0.14 + y * 0.09 + t * 3.8) * Math.sin(x * 0.09 - y * 0.14 + t * 2.8) * 0.12;
  const blend = reaction1 * 0.5 + pattern2 * 0.35 + fine;
  const v = blend * 0.5 + 0.5;
  const pal = [[8,14,56],[18,55,108],[42,125,142],[115,190,168],[205,195,85],[215,135,58],[175,68,48],[85,22,42],[8,14,56]];
  const idx = v * (pal.length - 1), i = Math.min(idx | 0, pal.length - 2), f = idx - i;
  const lum = 0.78 + Math.sin(reaction1 * 4.71) * 0.15 + Math.sin(pattern2 * 3.14) * 0.07;
  const vig = 1 - Math.sqrt((x - 240) ** 2 / 230400 + (y - 120) ** 2 / 57600) * 0.25;
